plugins {
    // Apply the application plugin to add support for building a CLI application in Java.
    application
    id("io.freefair.lombok") version "9.8.3"
    id("com.diffplug.spotless") version "8.11.0"
    id("maven-publish")
}

spotless {
    java {
        googleJavaFormat().aosp()

        // Optionally, add other steps
        formatAnnotations()
        removeUnusedImports()
        trimTrailingWhitespace()
        endWithNewline()

        // Specify target files (e.g., all .java files except those in build directory)
        target("src/**/*.java")
        targetExclude("build/**")
    }
}
version = "3.0.0"
group = "dev.joguenco.printer"

repositories {
    // Use Maven Central for resolving dependencies.
    mavenCentral()
    // Required by jasperreports-pdf, which depends on the Jaspersoft-patched version of OpenPDF.
    maven {
        url = uri("https://jaspersoft.jfrog.io/jaspersoft/third-party-ce-artifacts/")
    }
}

dependencies {
    implementation("com.sun.xml.ws:jaxws-rt:4.0.5")
    implementation("net.sf.jasperreports:jasperreports:7.1.1")
    // Since JasperReports 7, PDF export and Barcode4J support live in separate modules.
    implementation("net.sf.jasperreports:jasperreports-pdf:7.1.1")
    implementation("net.sf.jasperreports:jasperreports-barcode4j:7.1.1")
    compileOnly("org.projectlombok:lombok:1.18.48")

    // Use JUnit Jupiter for testing.
    testImplementation("org.junit.jupiter:junit-jupiter:5.9.3")

    testRuntimeOnly("org.junit.platform:junit-platform-launcher")
}

// Apply a specific Java toolchain to ease working on different environments.
java {
    toolchain {
        languageVersion.set(JavaLanguageVersion.of(21))
    }
}

application {
    // Define the main class for the application.
    mainClass.set("roquiprinter.App")
}

tasks.named<Test>("test") {
    // Use JUnit Platform for unit tests.
    useJUnitPlatform()
}

tasks.jar {
    // Customize the JAR file name
    archiveFileName.set("RoQuiPrinter-$version.jar")
}

publishing {
    publications {
        create<MavenPublication>("mavenJava") {
            artifactId = "RoQuiPrinter"
            from(components["java"])
            pom {
                name.set("RoQuiPrinter")
                description.set("Library to generate PDF for SRI documents electronics of Ecuador")
            }
        }
    }
    repositories {
        mavenLocal()
    }
}
